SQL = """
CREATE FUNCTION protect_mdl_observation() RETURNS trigger AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'MDL observations cannot be deleted' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.excluded OR NOT NEW.excluded THEN
    RAISE EXCEPTION 'MDL observations allow only one exclusion' USING ERRCODE = 'check_violation';
  END IF;
  IF (to_jsonb(NEW) - ARRAY['excluded', 'exclusion_reason', 'excluded_by_id', 'excluded_at'])
     IS DISTINCT FROM
     (to_jsonb(OLD) - ARRAY['excluded', 'exclusion_reason', 'excluded_by_id', 'excluded_at']) THEN
    RAISE EXCEPTION 'MDL observation data cannot be changed' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER mdl_observation_immutable BEFORE UPDATE OR DELETE ON analytical_mdlobservation
FOR EACH ROW EXECUTE FUNCTION protect_mdl_observation();

CREATE FUNCTION protect_mdl_calculation() RETURNS trigger AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'MDL calculations cannot be deleted' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.decision <> '' OR NEW.decision NOT IN ('adopted', 'retained', 'rejected') THEN
    RAISE EXCEPTION 'MDL calculations allow only one review' USING ERRCODE = 'check_violation';
  END IF;
  IF (to_jsonb(NEW) - ARRAY['decision', 'reviewed_by_id', 'reviewed_at', 'review_note', 'adopted_mdl'])
     IS DISTINCT FROM
     (to_jsonb(OLD) - ARRAY['decision', 'reviewed_by_id', 'reviewed_at', 'review_note', 'adopted_mdl']) THEN
    RAISE EXCEPTION 'MDL calculation data cannot be changed' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER mdl_calculation_immutable BEFORE UPDATE OR DELETE ON analytical_mdlcalculation
FOR EACH ROW EXECUTE FUNCTION protect_mdl_calculation();
"""
